    ($SATQ$590f2187$SATQ$, $SATQ$7ea2442b-48e4-447b-a75d-c1614b613123$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.A.$SATQ$, $SATQ$Linear equations in one variable$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">If <math alttext="3 x minus 27 equals 24"><mrow>
